typedef float vm_num_t;

class vm_stack
{
public:
  char* SP;
  void pop(int n) { SP -= n; }
  char* get_SP() const { return SP; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

struct vector3d
{
  float x;
  float y;
  float z;
};

struct vector3d_list
{
  vector3d* start;
  vector3d* finish;
  vector3d* end_of_storage;
  unsigned size() const { return finish - start; }
};

typedef vector3d_list* vm_vector3d_list_t;
void error(const char*);

class slf_vector3d_list_size_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_vector3d_list_t me;
  };
  virtual bool operator()(vm_stack& stack, entry_t entry);
};

bool slf_vector3d_list_size_t::operator()(vm_stack& stack, entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  vm_num_t result = parms->me->size();
  if (!stack.push((char*)&result,sizeof(result)) )
    error( "script stack overflow" );
  return true;
}
